#if AAA_MOV_FFMPEG()
void	c_movie_ffmpeg::print_av_error( int av_err )
{

	CHAR buf[512];
	if( av_strerror( av_err, buf, 512 ) == 0 )
		ERR_PRINT_STRING( "FFMPEG AVERROR %d : %s", av_err, buf );
	else
		ERR_PRINT_STRING( "FFMPEG AVERROR %d : can't get more info from this error code", av_err );
}
#endif

AAA_ERR	c_movie_ffmpeg::open_specific()
{
	//init_thread();
	_rate 					= 1.0;
	_frame_delay = .0;
	_time_pos = .0f;
	//AVCodecContext*	tnp = avcodec_alloc_context();

#if AAA_MOV_FFMPEG()
	int	numBytes;

	C_PCHAR_C filename = get_filename();

	int av_err;

	//_p_Format_Ctx can be null in avformat_open_input
	//if( !_p_Format_Ctx )
	//{
	//	_p_Format_Ctx = avformat_alloc_context();
	//}

	// Open video file
#if 0
	if( !_p_Format_Ctx )
	{
		_p_Format_Ctx = avformat_alloc_context();
	}
	//	fn is gone
	av_err = av_open_input_file( &_p_Format_Ctx, filename, nullptr, 0, nullptr );
#else
	av_err = avformat_open_input( &_p_Format_Ctx, filename, nullptr, nullptr );
#endif
	if( av_err != 0 )
	{
		ERR_PRINT_STRING( "FFMPEG : could not open file %s", filename );
		print_av_error( av_err );
		return ERR_ANY;
	}

	// Retrieve stream information
#if 0
	if( !_p_Format_Ctx )
	{
		_p_Format_Ctx = avformat_alloc_context();
	}
	av_err = av_find_stream_info( _p_Format_Ctx );
#else
	av_err = avformat_find_stream_info( _p_Format_Ctx, nullptr );
#endif

	if( av_err < 0 )
	{
		ERR_PRINT_STRING( "FFMPEG : could not find stream in file %s", filename );
		print_av_error( av_err );
		return ERR_ANY;
	}
	if( IS_NULL( _p_Format_Ctx ) )
	{
		ERR_PRINT_STRING( "FFMPEG : Context is NULL" );
		return ERR_ANY;
	}
	// Find the first video stream
	_video_stream = -1;
	for( UINT32 i = 0; i < _p_Format_Ctx->nb_streams; i++ )
	{
		if( _p_Format_Ctx->streams[ i ]->codec->codec_type == AVMEDIA_TYPE_VIDEO )
		{
			set_fps( (REAL)_p_Format_Ctx->streams[ i ]->r_frame_rate.num / (REAL)_p_Format_Ctx->streams[ i ]->r_frame_rate.den );
			_video_stream = i;
			break;
		}
	}
	if( _video_stream == -1 )
	{
		ERR_PRINT_STRING( "FFMPEG : could not find video stream in file %s", filename );
	}

	// Get a pointer to the codec context for the video stream
	_p_Codec_Ctx = _p_Format_Ctx->streams[ _video_stream ]->codec;

	// Find the decoder for the video stream
	_p_Codec = avcodec_find_decoder( _p_Codec_Ctx->codec_id );
	if( IS_NULL( _p_Codec ) )
	{
		ERR_PRINT_STRING( "FFMPEG : could not find decoder %s", filename );
		return ERR_ANY;
	}

	// Open codec
	av_err = avcodec_open( _p_Codec_Ctx, _p_Codec );
	if( av_err < 0 )
	{
		ERR_PRINT_STRING( "FFMPEG : could not open codec %s", filename );
		print_av_error( av_err );
		return ERR_ANY;
	}

	INT32	size_x = _p_Codec_Ctx->width;
	INT32	size_y = _p_Codec_Ctx->height;
	_duration = (REAL)_p_Format_Ctx->duration / (REAL)AV_TIME_BASE;
	_frame_delay = av_q2d( _p_Codec_Ctx->time_base ) * 1000;

	// Hack to correct wrong frame rates that seem to be generated by some codecs
	if( _p_Codec_Ctx->time_base.num  > 1000 && _p_Codec_Ctx->time_base.den == 1 )
		_p_Codec_Ctx->time_base.den = 1000;

	// Allocate video frame
	_p_Frame = avcodec_alloc_frame();

	// Allocate an AVFrame structure
	_p_Frame_RGB = avcodec_alloc_frame();
	if( IS_NULL( _p_Frame_RGB ) )
	{
		return ERR_ANY;
	}

//	// Determine required buffer size and allocate buffer
	numBytes = avpicture_get_size( PIX_FMT_RGB32, size_x, size_y );
	_buffer = new UINT8[ numBytes ];

	// Assign appropriate parts of buffer to image planes in pFrameRGB
	avpicture_fill( (AVPicture *)_p_Frame_RGB, _buffer, PIX_FMT_RGB32, size_x, size_y );

//	INT32	fmt = _p_Codec_Ctx->pix_fmt;

//	aaa::PIXEL_TYPE		type	= aaa::PIXEL_TYPE::RGBA;		/// todofranz make use force pixel is used
	aaa::PIXEL_FORMAT	format	= aaa::PIXEL_FORMAT::RGBA_8;
	switch( get_force_out_pixel_format() )	//todoqqq put it in every path
	{
	case aaa::PIXEL_FORMAT_FORCE::R_8 :
		format		= aaa::PIXEL_FORMAT::R_8 ;
		_pix_fmt	= PIX_FMT_GRAY8;
		break;
	case aaa::PIXEL_FORMAT_FORCE::RGB_8 :
		format		= aaa::PIXEL_FORMAT::RGB_8;
		_pix_fmt	= PIX_FMT_BGR24;
		break;
	case aaa::PIXEL_FORMAT_FORCE::RGBA_8 :
	default :
		format		= aaa::PIXEL_FORMAT::RGBA_8;
		_pix_fmt	= PIX_FMT_RGB32;
		break;
	}

	set_flux_size_format( size_x, size_y, format );

	// Convert the image from its native format to RGB
	if( IS_NULL( _img_convert_ctx ) &&  _p_Codec_Ctx->pix_fmt != _pix_fmt )
	{
		_img_convert_ctx = sws_getContext(	size_x, size_y, _p_Codec_Ctx->pix_fmt,
											size_x, size_y, _pix_fmt, SWS_FAST_BILINEAR, nullptr, nullptr, nullptr );
		if( IS_NULL( _img_convert_ctx ) )
		{
			ERR_PRINT_STRING( "FFMPEG : Cannot initialize the conversion context" );
			return ERR_ANY; //exit(1);
		}
	}

	set_filename_full( filename );

	_b_update_trig = true;
	//start_loop_read();
	//_thread_ffmpeg->start();
	//_p_Codec_Ctx->bit_rate;
	return AAA_OK;
#else
	return ERR_UNIMPLEMENTED_YET;
#endif
}

void 	c_movie_ffmpeg::close_specific()
{
#if AAA_MOV_FFMPEG()
	close_thread();
#endif
	if( is_valid() )
	{
#if AAA_MOV_FFMPEG()
		if( IS_NOT_NULL( _img_convert_ctx ) )
		{
			sws_freeContext( _img_convert_ctx );
		}
		SAFE_DELETE( _buffer );
		if( IS_NOT_NULL( _p_Frame_RGB ) )
		{
			av_free( _p_Frame_RGB );
		}
		// Free the YUV frame
		if( IS_NOT_NULL( _p_Frame ) )
		{
			av_free( _p_Frame );
		}
		// Close the codec
		if( IS_NOT_NULL( _p_Codec_Ctx ) )
		{
			avcodec_close( _p_Codec_Ctx );
		}
		_p_Codec = nullptr;
		// Close the video file
		if( IS_NOT_NULL( _p_Format_Ctx ) )
		{
			av_close_input_file( _p_Format_Ctx );
		}
#endif
	}
}

