void	c_movie_ffmpeg::pause()
{
	set_playing( false );
}

void	c_movie_ffmpeg::play()
{
	if( !is_started() )
	{
		if( is_valid() )
		{
#if AAA_MOV_FFMPEG()
			set_started( true );
			set_playing( true );
			_original_pts = (double)av_gettime();
#endif
		}
	}
	else 
		set_playing( true );
}

void	c_movie_ffmpeg::stop()
{
	set_playing( false );
}


