#if AAA_MOV_FFMPEG()
INT32	c_movie_ffmpeg::lib_open_count = 0;

void	c_movie_ffmpeg::lib_open()
{
	if( lib_open_count++ == 0 )
	{
		b_dll_loaded = wrap_ffmpeg_Init() == 0;
		if( b_dll_loaded )
			av_register_all();
	}
}

void	c_movie_ffmpeg::lib_close()
{
	--lib_open_count;
	if( --lib_open_count == 0 && b_dll_loaded )
		wrap_ffmpeg_Term();
}
#endif

