void	c_movie_ffmpeg::update_async()
{
	//set_process_priority_class( PRIO_CLASS_LOW );
	set_thread_priority( THREAD_PRIO_NORMAL );
#if AAA_MOV_FFMPEG()
//	static	double	video_current_pts_time;
//	static	double	video_current_pts_time2 = 0.0;
	static	double	time_pos = 0.0;
	static	double	time_pos_old = 0;
//	static	double	frame_delay;
//	static	double	prv_frame_time = 0.0;
	static	bool	b_frame_ready = false;
	static	bool	b_rgb = false;
	AVPacket		packet;
	AVPacket*		pkt = &packet;

	av_init_packet( pkt );
	pkt->data = nullptr;
	pkt->size = 0;
	static	REAL	dt;

	if( ( is_playing() || _b_update_trig ) && is_valid() && _p_Codec_Ctx && _p_Format_Ctx )
	{
		_delta_t.update();
		dt += _delta_t.get_dt();
		{
			std::lock_guard<aaa::MUTEX> guard(*_lock_ffmpeg);
			
			int	frame_finished = 0;
			_b_update_trig = false;

			if( !b_frame_ready )
			{
				while ( !frame_finished )
				{
					int ret = av_read_frame( _p_Format_Ctx, pkt );
					if( ret >= 0 )
					{
					//	prv_frame_time = video_current_pts_time;
						// Is this a packet from the video stream?
						if( pkt->stream_index == _video_stream )
						{
							// Decode video frame
							avcodec_decode_video2( _p_Codec_Ctx, _p_Frame, &frame_finished, pkt );
							int64_t tmp64;
							if( pkt->pts == 0x8000000000000000 ) // AV_NOPTS_VALUE )
							{
								tmp64 = pkt->dts;
							}
							else
							{
								tmp64 = pkt->pts;
							}
							time_pos = (double)tmp64 * av_q2d( _p_Codec_Ctx->time_base ) * 1000.;// / _video_fps;
							if( time_pos < _time_pos )
							{
								GOOD_PRINT_STRING( "time_pos %f is < _time_pos %f, %f, old was %f", time_pos, _time_pos, (DOUBLE)tmp64, time_pos_old );
							}
							else
							{
								//GOOD_PRINT_STRING( " time is ok %f", time_pos );
							}
							time_pos_old = time_pos;
						}
						// Free the packet that was allocated by av_read_frame
						//if ( pkt->data )
						av_free_packet( pkt );
					}
					else if( ret == AVERROR_EOF )
					{
						// end of file
						if( is_loop() )
						{
							av_seek_frame( _p_Format_Ctx, _video_stream, 0, 0 );
							_time_pos = 0.0;
						}
					}
				}
				if( frame_finished )
				{
					b_frame_ready = true;
					b_rgb = false;
					if( IS_NOT_NULL( _img_convert_ctx ) && _p_Codec_Ctx->pix_fmt != _pix_fmt )
					{
						if( _p_Frame->data[ 0 ] )
						{
							sws_scale( _img_convert_ctx, _p_Frame->data, _p_Frame->linesize, 0, 
								get_size_y(), _p_Frame_RGB->data, _p_Frame_RGB->linesize );
							b_rgb = true;
						}
					}
				}
			}
			// Did we get a video frame?
			if( b_frame_ready && IS_NOT_NULL( _img_convert_ctx ) )
			{
				// check frame time
				if( dt > _frame_delay )
			//	if( time_pos - _time_pos > _frame_delay )
				{
					if( time_pos > _time_pos )
					{
	//					tbuf_inc( c_tbuf_master::CH_VIDEO_MOVE_FRAME, 1., "ffmpeg_move_frame" );
						got_frame( b_rgb ? (UINT8*)_p_Frame_RGB->data[0] : (UINT8*)_p_Frame->data[0], "FFMpeg Flux" );
	//					tbuf_dec( c_tbuf_master::CH_VIDEO_MOVE_FRAME, 1., "ffmpeg_move_frame" );
						//if ( b_rgb )
						//	got_frame( (UINT8*)_p_Frame_RGB->data[0] );
						//else
						//	got_frame( (UINT8*)_p_Frame->data[0] );
						//if( _p_Codec_Ctx->pix_fmt != _pix_fmt )
						//{
						//	sws_scale( _img_convert_ctx, _p_Frame->data, _p_Frame->linesize, 0, 
						//		_size_y, _p_Frame_RGB->data, _p_Frame_RGB->linesize );
						//	got_frame( (UINT8*)_p_Frame_RGB->data[0] );
						//}
						//else
						//	got_frame( (UINT8*)_p_Frame->data[0] );
						b_frame_ready = false;
						//video_current_pts_time2 = time_pos;
						//_time_pos = time_pos;
						//	_time_pos += _frame_delay;
						//if ( time_pos < _time_pos )
						//	GOOD_PRINT_STRING( "time_pos is < _time_pos" );
						_time_pos = time_pos;
						dt = 0.0;
					}
					else
					{
						b_frame_ready = false;
						dt = 0.0;
					}
				}
			}
		//}
		}
		spy::sleep( 1, "sleep c_movie_ffmpeg::update_async() playing" );
	}
	else
	{
		spy::sleep( 10, "sleep c_movie_ffmpeg::update_async() not playing" );
	}
	//if ( _b_close_thread )
	//	break;
	//}
	if( IS_NOT_NULL( pkt->data ) )
		av_free_packet( pkt );
#endif
}

#endif //#if AAA_USE_FFMPEG()
